'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isPositiveZero = require( '@stdlib/assert/is-positive-zero' );
var isNegativeZero = require( '@stdlib/assert/is-negative-zero' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var silu = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( silu instanceof Error )
};


// FIXTURES //

var largeNegative = require( './fixtures/python/silu_large_negative.json' );
var largePositive = require( './fixtures/python/silu_large_positive.json' );
var nearZero = require( './fixtures/python/silu_near_zero.json' );
var special = require( './fixtures/python/silu_special.json' );
var medium = require( './fixtures/python/silu_medium.json' );


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof silu, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `NaN` when provided `NaN`', opts, function test( t ) {
	var v = silu( NaN );
	t.strictEqual( isnan( v ), true, 'returns NaN' );
	t.end();
});

tape( 'the function returns `+Infinity` when provided `+Infinity`', opts, function test( t ) {
	var v = silu( PINF );
	t.strictEqual( v, PINF, 'returns +Infinity' );
	t.end();
});

tape( 'the function returns `-0.0` when provided `-Infinity`', opts, function test( t ) {
	var v = silu( NINF );
	t.strictEqual( isNegativeZero( v ), true, 'returns -0.0' );
	t.end();
});

tape( 'the function preserves the sign of zero', opts, function test( t ) {
	var v = silu( 0.0 );
	t.strictEqual( isPositiveZero( v ), true, 'returns +0.0' );

	v = silu( -0.0 );
	t.strictEqual( isNegativeZero( v ), true, 'returns -0.0' );
	t.end();
});

tape( 'the function does not return `NaN` for large inputs', opts, function test( t ) {
	var v;

	v = silu( 1e200 );
	t.strictEqual( isnan( v ), false, 'does not return NaN' );
	t.strictEqual( v, 1e200, 'returns x for very large positive x' );

	v = silu( -1e200 );
	t.strictEqual( isnan( v ), false, 'does not return NaN' );
	t.strictEqual( isNegativeZero( v ), true, 'returns -0.0' );

	v = silu( 1e308 );
	t.strictEqual( isnan( v ), false, 'does not return NaN' );
	t.strictEqual( v, 1e308, 'returns x for very large positive x' );

	v = silu( -1e308 );
	t.strictEqual( isnan( v ), false, 'does not return NaN' );
	t.strictEqual( isNegativeZero( v ), true, 'returns -0.0' );
	t.end();
});

tape( 'the function evaluates SiLU near zero', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var i;

	x = nearZero.x;
	expected = nearZero.expected;
	for ( i = 0; i < x.length; i++ ) {
		y = silu( x[ i ] );
		t.strictEqual( isAlmostSameValue( y, expected[ i ], 2 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates SiLU for moderate inputs', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var i;

	x = medium.x;
	expected = medium.expected;
	for ( i = 0; i < x.length; i++ ) {
		y = silu( x[ i ] );
		t.strictEqual( isAlmostSameValue( y, expected[ i ], 2 ), true, 'returns expected value' );
	}
	t.end();
});

